183	  readonly turnIndex: number;
184	  readonly speaker: 'author' | 'maia';
185	  readonly body: string;
186	  readonly at: string;
187	  readonly adjunct:
188	    | null
189	    | { readonly kind: 'direction'; readonly id: string; readonly instruction: string; readonly refersTo: string | null }
190	    | { readonly kind: 'version'; readonly id: string; readonly wording: string; readonly supersedes: string | null };
191	}
192	
193	/**
194	 * ⭐ One formulation in the authored succession.
195	 *
196	 * ⛔ THIS IS NOT A TURN, and the two are deliberately different structures:
197	 *
198	 *     turns      conversation order
199	 *     versions   authored succession
200	 *
201	 * ⛔ They are never merged into one timestamped feed. A version authored in the
202	 * composer has no turn at all, and a chronological merge would have to invent a
203	 * position for it among things that were said.
204	 */
205	export interface EditorialThreadVersion {
206	  readonly id: string;
207	  readonly author: VersionAuthor;
208	  readonly wording: string;
209	  readonly supersedes: string | null;
210	  readonly rationale: string | null;
211	}
212	
213	export interface EditorialThreadView {
214	  readonly threadId: string;
215	  readonly chainId: string;
216	  /**
217	   * ⭐ WHICH WORK THIS EXCHANGE BELONGS TO, so a surface can hold a per-Work
218	   * setting (WS-EDITORIAL-SCOPE-01 · sequence override).
219	   *
220	   * ⛔⛔ EXPOSING IT ON A READ IS NOT THE SAME AS ACCEPTING IT ON A WRITE. The
221	   * turn route's closed body still refuses `workId` and always must: a value
222	   * the server DERIVES is not a value the browser may assert. This is the
223	   * member's own Work, named to the member, on a member-scoped read.
224	   */
225	  readonly workId: string;
226	  /** ⭐ The writer's own wording at the locus, as the chain froze it. */
227	  readonly locusText: string;
228	  /**
229	   * ⭐ ADOPTION-01 · PHASE B — WHERE THIS EXCHANGE IS ABOUT, named by the
230	   * server. The id is the chain's own target; the label is the writer's own
231	   * heading for it.
232	   *
233	   * ⛔ `sectionLabel` is `null` when the section carries no heading, and it is
234	   * NEVER filled with a manufactured name. A confirmation that invents a place
235	   * name is the browser interpreting manuscript location, which is exactly what
236	   * the `ChangeLocator` law forbids.
237	   */
238	  readonly targetSectionId: string | null;
239	  readonly sectionLabel: string | null;
240	  /**
241	   * ⚠️ EDITORIAL-LEGACY-LOCUS-DISPOSITION-01 — this relationship's frozen locus
242	   * was written in the pre-alignment stored coordinate space and can never be
243	   * located in the projected one.
244	   *
245	   * ⭐ THE SURFACE NEEDS IT BEFORE SHE CHOOSES. Without it she would pick a
246	   * version, confirm an adoption, and only then meet a refusal — so the fact
247	   * that belongs to the relationship is reported with the relationship.
248	   *
249	   * ⛔ It withholds adoption and NOTHING ELSE. The exchange stays readable and
250	   * comparable; the chain is untouched; ⛔ nothing here says her Work moved.
251	   */
252	  readonly legacyLocus: boolean;
253	  readonly turns: readonly EditorialThreadTurn[];
254	  /**
255	   * ⭐⭐ THE COMPLETE STRUCTURAL LINEAGE, in succession order.
256	   *
257	   * ⚠️ UI-01 exposed versions ONLY through turn bindings, so a formulation
258	   * authored in a composer — which lawfully has no turn — would have been
259	   * DURABLE AND INVISIBLE. ⛔ The repair is not chronology: it is the chain's
260	   * own validated succession, read through `readProposalWork`, which already
261	   * owns read → validateChain → lineage. ⛔ No second ordering algorithm.
262	   */
263	  readonly application?: ApplicationRecovery | null;
264	  readonly versions: readonly EditorialThreadVersion[];
265	  /** ⭐ The head of that succession, or `null` when nothing is authored yet. */
266	  readonly headVersionId: string | null;
267	}
268	
269	export type ReadEditorialRefusal = 'thread_not_found' | 'not_editorial' | 'chain_unreadable';
270	
271	export type ReadEditorialResult =
272	  | { readonly ok: true; readonly view: EditorialThreadView }
273	  | { readonly ok: false; readonly reason: ReadEditorialRefusal };
274	
275	/**
276	 * ⭐⭐ THE CONVERSATION IS SERVER STATE. This is the whole reason the surface
277	 * survives close, reopen and navigation: nothing below is reconstructed from a
278	 * component, and there is no client transcript to disagree with it.
279	 */
280	export async function readEditorialThread(
281	  identity: VerifiedIdentity, threadId: string,
282	): Promise<ReadEditorialResult> {
283	  const memberId = identity.memberId;
284	  /* ⭐ ADOPTION-01 · PHASE B — the target section and the writer's own name for
285	     it, DERIVED HERE, in the read that already proves thread ownership.
286	     ⛔ The browser must never name the place a change belongs; that is the
287	     `ChangeLocator` law one layer up, and it starts with the label. */
288	  const t = await query<{
289	    proposal_chain_id: string | null; expected_text: string | null;
290	    target_section_id: string | null; heading: string | null;
291	  }>(
292	    `SELECT th.proposal_chain_id, c.expected_text, c.target_section_id, ms.heading
293	       FROM ask_threads th
294	       LEFT JOIN proposal_chains c ON c.id = th.proposal_chain_id
295	       LEFT JOIN manuscript_draft_sections ds ON ds.id = c.target_section_id
296	       LEFT JOIN manuscript_sections ms ON ms.id = ds.source_section_id
297	      WHERE th.id = $1 AND th.member_id = $2`,
298	    [threadId, memberId]);
299	  if (t.rows.length === 0) return { ok: false, reason: 'thread_not_found' };
300	  const chainId = t.rows[0]!.proposal_chain_id;
301	  if (chainId === null) return { ok: false, reason: 'not_editorial' };
302	
303	  /* ⭐ ONE READ, LEFT-JOINED THROUGH THE BINDING. The adjunct arrives because a
304	     binding names it — ⛔ not because a turn's text resembles one. */
305	  const rows = await query<{
306	    turn_index: number; speaker: string; body: string; created_at: Date;
307	    direction_id: string | null; instruction: string | null; refers_to_version_id: string | null;
308	    version_id: string | null; formulation: string | null; supersedes: string | null;
309	  }>(
310	    `SELECT tu.turn_index, tu.speaker, tu.body, tu.created_at,
311	            b.direction_id, d.instruction, d.refers_to_version_id,
312	            b.version_id, v.formulation, v.supersedes
313	       FROM ask_turns tu
314	       LEFT JOIN editorial_turn_bindings b
315	              ON b.thread_id = tu.thread_id AND b.turn_index = tu.turn_index
316	       LEFT JOIN proposal_chain_directions d ON d.id = b.direction_id
317	       LEFT JOIN proposal_versions v ON v.id = b.version_id
318	      WHERE tu.thread_id = $1
319	      ORDER BY tu.turn_index`,
320	    [threadId]);
321	
322	  const turns: EditorialThreadTurn[] = rows.rows.map((r) => ({
323	    turnIndex: Number(r.turn_index),
324	    speaker: r.speaker === 'maia' ? 'maia' : 'author',
325	    body: r.body,
326	    at: new Date(r.created_at).toISOString(),
327	    adjunct: r.direction_id
328	      ? { kind: 'direction', id: r.direction_id, instruction: r.instruction ?? '', refersTo: r.refers_to_version_id }
329	      : r.version_id
330	        ? { kind: 'version', id: r.version_id, wording: r.formulation ?? '', supersedes: r.supersedes }
331	        : null,
332	  }));
333	
334	  /* ⭐ THE SUCCESSION, FROM THE READ THAT ALREADY VALIDATES IT. A corrupt chain
335	     REFUSES here exactly as it refuses there — ⛔ a view that quietly worked
336	     around broken succession would show the writer a history nobody authored. */
337	  const work = await readProposalWork(memberId, chainId);
338	  if (!work.ok) return { ok: false, reason: 'chain_unreadable' };
339	  const versions: EditorialThreadVersion[] = work.work.versions.map((v) => ({
340	    id: v.id,
341	    author: v.author,
342	    wording: v.replacementText,
343	    supersedes: v.supersedes,
344	    rationale: v.rationale ?? null,
345	  }));
346	
347	  return {
348	    ok: true,
349	    view: {
350	      application: await readApplicationRecovery(memberId, threadId),
351	      threadId, chainId,
352	      /* ⭐ From the same validated read as the succession. ⛔ Not a second lookup. */
353	      workId: work.work.chain.locus.workId,
354	      locusText: t.rows[0]!.expected_text ?? '',
355	      targetSectionId: t.rows[0]!.target_section_id,
356	      sectionLabel: t.rows[0]!.heading,
357	      /* ⭐ THE SAME PURE PREDICATE THE ADOPTION SEAM ASKS — one implementation,
358	         so the panel and the act can never disagree about which relationships
359	         are adoptable. */
360	      legacyLocus: !locusIsAdoptable(t.rows[0]!.expected_text ?? '', t.rows[0]!.heading),
361	      turns,
362	      versions,
363	      /* ⛔ Read off the LINEAGE, never off `versions[length-1]` of an unordered
364	         read — `readProposalWork` returns them in succession order. */
365	      headVersionId: versions.length ? versions[versions.length - 1]!.id : null,
366	    },
367	  };
368	}
