  if (existing) {
    if (existing.relationship_id !== input.relationshipId) {
      throw new RelationshipCustodyRefused('child_already_attached_elsewhere');
    }
    return { id: existing.id, sequence: Number(existing.sequence), existing: true as const };
  }
