1	/**
2	 * WRITERS-STUDIO-NEXT-01 / A2-7 — durable return state.
3	 * Relationship return and manuscript place are separate member-owned records.
4	 * Neither one authorizes, derives or rewrites the other.
5	 */
6	import { query, transaction, type TransactionClient } from '@/lib/db/postgres';
7	
8	export type ReturnStateRefusal =
9	  | 'scope_unavailable'
10	  | 'relationship_unavailable'
11	  | 'place_unavailable';
12	
13	export interface ReturnScope {
14	  readonly memberId: string;
15	  readonly livingWorkId: string;
16	  readonly manuscriptId: string;
17	}
18	
19	async function validateScope(tx: TransactionClient, input: ReturnScope): Promise<boolean> {
20	  const r = await tx.query(
21	    `SELECT 1
22	       FROM living_works w
23	       JOIN member_manuscripts m ON m.id = $3 AND m.member_id = $1
24	      WHERE w.id = $2
25	        AND w.member_id = $1
26	        AND EXISTS (
27	          SELECT 1 FROM living_work_expressions e
28	           WHERE e.living_work_id = w.id
29	             AND e.expression_type = 'manuscript'
30	             AND e.expression_id = m.id
31	             AND e.declared_by = $1
32	        )
