23	import { query, transaction } from '@/lib/db/postgres';
24	import { splitStoredSection } from '@/lib/manuscript/sections/sectionProjection';
25	import { projectEditorialSelection, type EditorialSelectionRange } from './selection';
26	import { locusIsAdoptable } from '../proposalChain/legacyLocus';
27	import { openChainWithExecutor } from '../proposalChain/store';
