29	import type { VersionAuthor } from '../proposalChain/contract';
30	import type { VerifiedIdentity } from './turn';
31	
32	export interface OpenEditorialInput {
33	  readonly identity: VerifiedIdentity;
34	  /**
35	   * ⭐ THE ONLY THING THE MEMBER NAMES: the section they selected.
36	   * ⛔ The locus — work, draft, base version, expected text — is DERIVED here,
37	   * never accepted, for the same reason the turn route refuses a `chainId`.
38	   */
39	  readonly sectionId: string;
40	}
41	
42	export interface OpenEditorialSelectionInput extends OpenEditorialInput {
43	  /** Unicode code points inside the projected section body. Prose never travels. */
44	  readonly range: EditorialSelectionRange;
45	  /** The draft version the browser selected against. Used only to refuse stale coordinates. */
46	  readonly revisionNumber: number;
47	}
48	
49	/**
50	 * ⭐ EDITORIAL-LOCUS-ALIGNMENT-01 · PHASE B — two refusals where the passage
51	 * cannot be named.
52	 *
53	 * ⛔ `section_unprojectable` — the stored slice is not in the shape this cut
54	 * knows how to project, so there is no editable passage to point at. ⭐ Refusing
55	 * to OPEN is the honest answer: a relationship whose locus can never be located
56	 * would later report a manuscript fact that is not true.
57	 *
58	 * ⚠️ `section_has_no_body` IS A JUDGMENT CALL, FLAGGED. A section that is only a
59	 * heading projects to the empty string, and `occurrences(body, '')` is 0 by the
60	 * exact-text law's own zero-length guard — so such a chain could never match,
61	 * ever, and would reproduce exactly the defect this act closes. It is named
62	 * separately rather than folded into the one above, because *cannot be
63	 * projected* and *projects to nothing* are two different facts about the
64	 * writer's page.
65	 */
66	export type OpenEditorialRefusal =
67	  | 'section_not_found'
68	  | 'section_unprojectable'
69	  | 'section_has_no_body'
70	  | 'selection_stale'
71	  | 'selection_invalid'
72	  | 'selection_ambiguous'
73	  | 'chain_refused';
74	
75	export type OpenEditorialResult =
76	  | { readonly ok: true; readonly threadId: string; readonly chainId: string }
77	  | { readonly ok: false; readonly reason: OpenEditorialRefusal; readonly detail?: string };
78	
79	/**
80	 * ⭐⭐ ONE DURABLE ACT. The chain and the conversation about it are opened
81	 * together or not at all — the W5-4 law: *failure may leave neither half
82	 * pretending the other happened.*
83	 */
84	export async function openEditorialRelationship(
85	  input: OpenEditorialInput,
86	): Promise<OpenEditorialResult> {
87	  return openEditorialRelationshipResolved(input, null);
88	}
89	
90	/**
91	 * Rebuild-only passage door. The member names coordinates, never manuscript
92	 * prose. The server rereads the section under ownership, verifies that the
93	 * draft has not advanced since selection, derives the exact characters, and
94	 * opens the same governed chain/thread pair the section door opens.
95	 */
96	export async function openEditorialRelationshipAtSelection(
97	  input: OpenEditorialSelectionInput,
98	): Promise<OpenEditorialResult> {
99	  return openEditorialRelationshipResolved(input, {
100	    range: input.range, revisionNumber: input.revisionNumber,
101	  });
102	}
103	
104	async function openEditorialRelationshipResolved(
105	  input: OpenEditorialInput,
106	  selection: { readonly range: EditorialSelectionRange; readonly revisionNumber: number } | null,
107	): Promise<OpenEditorialResult> {
108	  const memberId = input.identity.memberId;
109	  try {
110	    return await transaction(async (tx) => {
111	      const s = await tx.query<{
112	        draft_id: string; manuscript_id: string; revision_count: number; draft_version: string;
113	        text: string; heading: string | null;
114	      }>(
115	        `SELECT s.draft_id, d.manuscript_id, d.revision_count, d.version AS draft_version,
116	                s.text, ms.heading
117	           FROM manuscript_draft_sections s
118	           JOIN manuscript_working_drafts d ON d.id = s.draft_id
119	           LEFT JOIN manuscript_sections ms ON ms.id = s.source_section_id
120	          WHERE s.id = $1 AND d.member_id = $2`,
121	        [input.sectionId, memberId]);
122	      if (s.rows.length === 0) throw new OpenRefused('section_not_found');
123	      const row = s.rows[0]!;
124	
125	      const split = splitStoredSection(row.text, row.heading);
126	      if (!split) throw new OpenRefused('section_unprojectable');
127	      if (split.body.length === 0) throw new OpenRefused('section_has_no_body');
128	
129	      let expectedText = split.body;
130	      if (selection) {
131	        if (!Number.isInteger(selection.revisionNumber)
132	            || Number(row.draft_version) !== selection.revisionNumber) {
133	          throw new OpenRefused('selection_stale');
134	        }
135	        const projected = projectEditorialSelection(split.body, selection.range);
136	        if (!projected.ok) {
137	          const reason = projected.reason === 'selection_ambiguous'
138	            ? 'selection_ambiguous' : 'selection_invalid';
139	          throw new OpenRefused(reason);
140	        }
141	        expectedText = projected.text;
142	      }
143	
144	      const chain = await openChainWithExecutor(tx, memberId, {
145	        locus: {
146	          workId: row.manuscript_id,
147	          draftId: row.draft_id,
148	          baseVersion: Number(row.revision_count),
149	          targetSectionId: input.sectionId,
150	          locusScopeKind: selection === null ? 'section' : 'passage',
151	          expectedText,
152	        },
153	      });
154	
155	      const t = await tx.query<{ id: string }>(
156	        `INSERT INTO ask_threads
157	           (manuscript_id, member_id, anchor, reading_identity,
158	            canonical_at_open, initiated_by, proposal_chain_id)
159	         VALUES ($1, $2, NULL, NULL, $3, 'author', $4)
160	         RETURNING id`,
161	        [row.manuscript_id, memberId, `draft:${row.draft_id}@${row.revision_count}`, chain.id]);
162	
163	      return { ok: true as const, threadId: t.rows[0]!.id, chainId: chain.id };
164	    });
165	  } catch (e) {
166	    if (e instanceof OpenRefused) return { ok: false, reason: e.reason, detail: e.detail };
167	    throw e;
168	  }
169	}
170	
171	class OpenRefused extends Error {
172	  constructor(readonly reason: OpenEditorialRefusal, readonly detail?: string) { super(reason); }
173	}
174	
175	/* ══════════════════════════════════════════════════════════════════════════
176	   READ — what the surface renders
177	   ══════════════════════════════════════════════════════════════════════════ */
178	
179	/**
180	 * ⭐ One rendered turn. The adjunct is the RELATIONSHIP the binding records —
181	 * ⛔ never inferred from what the turn happens to say.
182	 */
183	export interface EditorialThreadTurn {
184	  readonly turnIndex: number;
185	  readonly speaker: 'author' | 'maia';
186	  readonly body: string;
187	  readonly at: string;
188	  readonly adjunct:
189	    | null
190	    | { readonly kind: 'direction'; readonly id: string; readonly instruction: string; readonly refersTo: string | null }
191	    | { readonly kind: 'version'; readonly id: string; readonly wording: string; readonly supersedes: string | null };
192	}
193	
194	/**
195	 * ⭐ One formulation in the authored succession.
196	 *
197	 * ⛔ THIS IS NOT A TURN, and the two are deliberately different structures:
198	 *
199	 *     turns      conversation order
200	 *     versions   authored succession
201	 *
202	 * ⛔ They are never merged into one timestamped feed. A version authored in the
203	 * composer has no turn at all, and a chronological merge would have to invent a
204	 * position for it among things that were said.
205	 */
206	export interface EditorialThreadVersion {
207	  readonly id: string;
208	  readonly author: VersionAuthor;
209	  readonly wording: string;
210	  readonly supersedes: string | null;
211	  readonly rationale: string | null;
212	}
213	
214	export interface EditorialThreadView {
215	  readonly threadId: string;
216	  readonly chainId: string;
217	  /**
218	   * ⭐ WHICH WORK THIS EXCHANGE BELONGS TO, so a surface can hold a per-Work
219	   * setting (WS-EDITORIAL-SCOPE-01 · sequence override).
220	   *
221	   * ⛔⛔ EXPOSING IT ON A READ IS NOT THE SAME AS ACCEPTING IT ON A WRITE. The
222	   * turn route's closed body still refuses `workId` and always must: a value
223	   * the server DERIVES is not a value the browser may assert. This is the
224	   * member's own Work, named to the member, on a member-scoped read.
225	   */
226	  readonly workId: string;
227	  /** ⭐ The writer's own wording at the locus, as the chain froze it. */
228	  readonly locusText: string;
229	  /**
230	   * ⭐ ADOPTION-01 · PHASE B — WHERE THIS EXCHANGE IS ABOUT, named by the
231	   * server. The id is the chain's own target; the label is the writer's own
232	   * heading for it.
233	   *
234	   * ⛔ `sectionLabel` is `null` when the section carries no heading, and it is
235	   * NEVER filled with a manufactured name. A confirmation that invents a place
236	   * name is the browser interpreting manuscript location, which is exactly what
237	   * the `ChangeLocator` law forbids.
238	   */
239	  readonly targetSectionId: string | null;
240	  readonly sectionLabel: string | null;
241	  /**
242	   * ⚠️ EDITORIAL-LEGACY-LOCUS-DISPOSITION-01 — this relationship's frozen locus
243	   * was written in the pre-alignment stored coordinate space and can never be
244	   * located in the projected one.
245	   *
246	   * ⭐ THE SURFACE NEEDS IT BEFORE SHE CHOOSES. Without it she would pick a
247	   * version, confirm an adoption, and only then meet a refusal — so the fact
248	   * that belongs to the relationship is reported with the relationship.
249	   *
250	   * ⛔ It withholds adoption and NOTHING ELSE. The exchange stays readable and
251	   * comparable; the chain is untouched; ⛔ nothing here says her Work moved.
252	   */
253	  readonly legacyLocus: boolean;
254	  readonly turns: readonly EditorialThreadTurn[];
255	  /**
256	   * ⭐⭐ THE COMPLETE STRUCTURAL LINEAGE, in succession order.
257	   *
258	   * ⚠️ UI-01 exposed versions ONLY through turn bindings, so a formulation
259	   * authored in a composer — which lawfully has no turn — would have been
260	   * DURABLE AND INVISIBLE. ⛔ The repair is not chronology: it is the chain's
261	   * own validated succession, read through `readProposalWork`, which already
262	   * owns read → validateChain → lineage. ⛔ No second ordering algorithm.
263	   */
264	  readonly application?: ApplicationRecovery | null;
265	  readonly versions: readonly EditorialThreadVersion[];
266	  /** ⭐ The head of that succession, or `null` when nothing is authored yet. */
267	  readonly headVersionId: string | null;
268	}
269	
270	export type ReadEditorialRefusal = 'thread_not_found' | 'not_editorial' | 'chain_unreadable';
271	
272	export type ReadEditorialResult =
273	  | { readonly ok: true; readonly view: EditorialThreadView }
274	  | { readonly ok: false; readonly reason: ReadEditorialRefusal };
275	
276	/**
277	 * ⭐⭐ THE CONVERSATION IS SERVER STATE. This is the whole reason the surface
278	 * survives close, reopen and navigation: nothing below is reconstructed from a
279	 * component, and there is no client transcript to disagree with it.
280	 */
281	export async function readEditorialThread(
282	  identity: VerifiedIdentity, threadId: string,
283	): Promise<ReadEditorialResult> {
284	  const memberId = identity.memberId;
285	  /* ⭐ ADOPTION-01 · PHASE B — the target section and the writer's own name for
286	     it, DERIVED HERE, in the read that already proves thread ownership.
287	     ⛔ The browser must never name the place a change belongs; that is the
288	     `ChangeLocator` law one layer up, and it starts with the label. */
289	  const t = await query<{
290	    proposal_chain_id: string | null; expected_text: string | null;
291	    target_section_id: string | null; heading: string | null;
292	  }>(
293	    `SELECT th.proposal_chain_id, c.expected_text, c.target_section_id, ms.heading
294	       FROM ask_threads th
295	       LEFT JOIN proposal_chains c ON c.id = th.proposal_chain_id
296	       LEFT JOIN manuscript_draft_sections ds ON ds.id = c.target_section_id
297	       LEFT JOIN manuscript_sections ms ON ms.id = ds.source_section_id
298	      WHERE th.id = $1 AND th.member_id = $2`,
299	    [threadId, memberId]);
300	  if (t.rows.length === 0) return { ok: false, reason: 'thread_not_found' };
301	  const chainId = t.rows[0]!.proposal_chain_id;
302	  if (chainId === null) return { ok: false, reason: 'not_editorial' };
303	
304	  /* ⭐ ONE READ, LEFT-JOINED THROUGH THE BINDING. The adjunct arrives because a
305	     binding names it — ⛔ not because a turn's text resembles one. */
306	  const rows = await query<{
307	    turn_index: number; speaker: string; body: string; created_at: Date;
308	    direction_id: string | null; instruction: string | null; refers_to_version_id: string | null;
309	    version_id: string | null; formulation: string | null; supersedes: string | null;
310	  }>(
311	    `SELECT tu.turn_index, tu.speaker, tu.body, tu.created_at,
312	            b.direction_id, d.instruction, d.refers_to_version_id,
313	            b.version_id, v.formulation, v.supersedes
314	       FROM ask_turns tu
315	       LEFT JOIN editorial_turn_bindings b
316	              ON b.thread_id = tu.thread_id AND b.turn_index = tu.turn_index
317	       LEFT JOIN proposal_chain_directions d ON d.id = b.direction_id
318	       LEFT JOIN proposal_versions v ON v.id = b.version_id
319	      WHERE tu.thread_id = $1
320	      ORDER BY tu.turn_index`,
321	    [threadId]);
322	
323	  const turns: EditorialThreadTurn[] = rows.rows.map((r) => ({
324	    turnIndex: Number(r.turn_index),
325	    speaker: r.speaker === 'maia' ? 'maia' : 'author',
326	    body: r.body,
327	    at: new Date(r.created_at).toISOString(),
328	    adjunct: r.direction_id
329	      ? { kind: 'direction', id: r.direction_id, instruction: r.instruction ?? '', refersTo: r.refers_to_version_id }
330	      : r.version_id
331	        ? { kind: 'version', id: r.version_id, wording: r.formulation ?? '', supersedes: r.supersedes }
332	        : null,
333	  }));
334	
335	  /* ⭐ THE SUCCESSION, FROM THE READ THAT ALREADY VALIDATES IT. A corrupt chain
336	     REFUSES here exactly as it refuses there — ⛔ a view that quietly worked
337	     around broken succession would show the writer a history nobody authored. */
338	  const work = await readProposalWork(memberId, chainId);
339	  if (!work.ok) return { ok: false, reason: 'chain_unreadable' };
340	  const versions: EditorialThreadVersion[] = work.work.versions.map((v) => ({
341	    id: v.id,
342	    author: v.author,
343	    wording: v.replacementText,
344	    supersedes: v.supersedes,
345	    rationale: v.rationale ?? null,
346	  }));
347	
348	  return {
349	    ok: true,
350	    view: {
351	      application: await readApplicationRecovery(memberId, threadId),
352	      threadId, chainId,
353	      /* ⭐ From the same validated read as the succession. ⛔ Not a second lookup. */
354	      workId: work.work.chain.locus.workId,
355	      locusText: t.rows[0]!.expected_text ?? '',
356	      targetSectionId: t.rows[0]!.target_section_id,
357	      sectionLabel: t.rows[0]!.heading,
358	      /* ⭐ THE SAME PURE PREDICATE THE ADOPTION SEAM ASKS — one implementation,
359	         so the panel and the act can never disagree about which relationships
360	         are adoptable. */
361	      legacyLocus: !locusIsAdoptable(t.rows[0]!.expected_text ?? '', t.rows[0]!.heading),
362	      turns,
363	      versions,
364	      /* ⛔ Read off the LINEAGE, never off `versions[length-1]` of an unordered
365	         read — `readProposalWork` returns them in succession order. */
366	      headVersionId: versions.length ? versions[versions.length - 1]!.id : null,
367	    },
368	  };
369	}
