1	/**
2	 * WS-EDITORIAL-RUNTIME-01 · ER-R5 — THE THIN EDITORIAL TURN DOOR.
3	 *
4	 * ⭐⭐ THIN MEANS THIN. This route establishes WHO is acting and WHAT they
5	 * declared, and then gets out of the way. ⛔ It is not a second authority layer:
6	 * every other fact the runtime needs is a SERVER fact, derived here or deeper.
7	 *
8	 * ⛔ FOUNDER-GATED AND OFF BY DEFAULT. Without `WRITERS_STUDIO_EDITORIAL_ENABLED`
9	 * it 404s — it does not 403. An unauthorized caller learns nothing about what
10	 * exists behind it. (The Focus route's posture, followed rather than reinvented.)
11	 *
12	 * ── ⭐⭐ THE ORDER IS THE LAW ──────────────────────────────────────────────
13	 *
14	 *   gate → identity → verified only → CLOSED parse → posture
15	 *        → ⛔ SANCTUARY REFUSES HERE, BEFORE ANY WRITE
16	 *        → R1 persist → mint exchangeId → R4 turn → thin response
17	 *
18	 * ⛔⛔ THE SANCTUARY REFUSAL IS BEFORE R1 AND THAT POSITION IS THE POINT. The
19	 * editorial stores are DURABLE and there is no ruled ephemeral editorial
20	 * equivalent. A member's words must not reach `ask_turns` and only then
21	 * discover that Sanctuary meant they should never have been written.
22	 */
23	
24	import { NextResponse, type NextRequest } from 'next/server';
25	import { randomUUID } from 'node:crypto';
26	import { resolveCanonicalIdentity } from '@/lib/maia/canonical-turn';
27	import { TurnPosture } from '@/lib/sanctuary/turnPosture';
28	import { persistMemberEditorialAct } from '@/lib/manuscript/editorialRuntime/memberAct';
29	import { runEditorialTurn } from '@/lib/manuscript/editorialRuntime/turn';
30	import { MEMBER_ACT_KINDS, type MemberActKind } from '@/lib/manuscript/editorialDiscourse/contract';
31	import { preflightEditorialRelationshipCarriage, resolvePriorMaiaEditorialCarry, type ResolvedPriorMaiaEditorialCarry } from '@/lib/writers-studio/relationshipCarriage';
32	import {
33	  DEFAULT_SCOPE_DECLARATION, isEditorialLatitude,
34	  type EditorialScopeDeclaration,
35	} from '@/lib/manuscript/editorialScope/contract';
36	import type { ProposalPolicy } from '@/lib/manuscript/editorialScope/sequence';
37	
38	export const dynamic = 'force-dynamic';
39	
40	const enabled = () => process.env.WRITERS_STUDIO_EDITORIAL_ENABLED === '1';
41	
42	/**
43	 * ⭐⭐ A CLOSED SHAPE, NOT A TOLERANT ONE.
44	 *
45	 * ⛔ Unknown keys are REFUSED, never ignored. A caller that sends `chainId` and
46	 * receives 200 would be left believing that value had standing — and the next
47	 * person to read their code would believe it too. The refusal names the keys so
48	 * the mistake is legible rather than mysterious.
49	 */
50	const TOP_KEYS = [
51	  'threadId', 'act', 'sanctuary', 'scope', 'proposalPolicy', 'relationshipId', 'carry',
52	] as const;
53	const CARRY_KEYS = ['kind', 'sourceEpisodeSequence'] as const;
54	const ACT_KEYS = ['act', 'text', 'refersTo'] as const;
55	/**
56	 * ⭐⭐ THE AUTHOR'S TWO CONTROLS, AND THEY ARE SEPARATE KEYS ON PURPOSE.
57	 *
58	 * ⛔ `mayRemoveParagraphs` is NOT derivable from `latitude`. A surface that
59	 * wants both must send both, and a surface that sends neither gets the most
60	 * protective setting — never a permission it did not ask for.
61	 */
62	const SCOPE_KEYS = ['latitude', 'mayRemoveParagraphs', 'mayProposeImmediately'] as const;
63	
64	type Parsed =
65	  | {
66	      ok: true; threadId: string;
67	      act: { act: MemberActKind; text: string; refersTo: string | null };
68	      sanctuary: boolean;
69	      scope: EditorialScopeDeclaration;
70	      relationshipId: string | null;
71	      carry: { kind: 'prior_maia_editorial_turn'; sourceEpisodeSequence: number } | null;
72	      /** ⭐ The writer's PER-WORK release of the sequence gate. ⛔ Default false. */
73	      mayProposeImmediately: boolean;
74	      /** Turn-local outcome vocabulary. ⛔ Defaults to allow. */
75	      proposalPolicy: ProposalPolicy;
76	    }
77	  | { ok: false; error: string };
78	
79	function parseClosed(body: unknown): Parsed {
80	  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
81	    return { ok: false, error: 'a JSON object is required' };
82	  }
83	  const b = body as Record<string, unknown>;
84	  const strayTop = Object.keys(b).filter((k) => !(TOP_KEYS as readonly string[]).includes(k));
85	  if (strayTop.length) {
86	    return { ok: false, error: `unknown field(s): ${strayTop.join(', ')} — these are server facts and carry no standing here` };
87	  }
88	  /* SANCTUARY-EDITORIAL-PERSISTENCE-01 / E1 — posture is REQUIRED, and it is
89	     checked before the act is examined. A member turn is durable (ask_turns +
90	     editorial_turn_bindings); absence or a malformed value is an UNRESOLVED
91	     posture, never ordinary. The route maps this to 400 posture_required. */
92	  if (typeof b.sanctuary !== 'boolean') {
93	    return { ok: false, error: 'posture_required' };
94	  }
95	  if (typeof b.threadId !== 'string' || b.threadId.length === 0) {
96	    return { ok: false, error: 'threadId is required' };
97	  }
98	  if (!(b.relationshipId === undefined
99	      || (typeof b.relationshipId === 'string' && b.relationshipId.length > 0))) {
100	    return { ok: false, error: 'relationshipId must be a non-empty string when provided' };
101	  }
102	
103	  let carry: { kind: 'prior_maia_editorial_turn'; sourceEpisodeSequence: number } | null = null;
104	  if (b.carry !== undefined) {
105	    if (typeof b.relationshipId !== 'string' || b.relationshipId.length === 0) {
106	      return { ok: false, error: 'relationship_required' };
107	    }
108	    if (typeof b.carry !== 'object' || b.carry === null || Array.isArray(b.carry)) {
109	      return { ok: false, error: 'carry must be an object' };
110	    }
111	    const co = b.carry as Record<string, unknown>;
112	    const strayCarry = Object.keys(co).filter((k) => !(CARRY_KEYS as readonly string[]).includes(k));
113	    if (strayCarry.length) return { ok: false, error: `unknown carry field(s): ${strayCarry.join(', ')}` };
114	    if (co.kind !== 'prior_maia_editorial_turn') {
115	      return { ok: false, error: 'carry.kind must be prior_maia_editorial_turn' };
116	    }
117	    if (!Number.isInteger(co.sourceEpisodeSequence) || Number(co.sourceEpisodeSequence) < 1) {
118	      return { ok: false, error: 'carry.sourceEpisodeSequence must be a positive integer' };
119	    }
120	    carry = { kind: 'prior_maia_editorial_turn', sourceEpisodeSequence: Number(co.sourceEpisodeSequence) };
121	  }
122	  const a = b.act;
123	  if (typeof a !== 'object' || a === null || Array.isArray(a)) {
124	    return { ok: false, error: 'act is required' };
125	  }
126	  const ao = a as Record<string, unknown>;
127	  const strayAct = Object.keys(ao).filter((k) => !(ACT_KEYS as readonly string[]).includes(k));
128	  if (strayAct.length) {
129	    return { ok: false, error: `unknown act field(s): ${strayAct.join(', ')}` };
130	  }
131	  /* ⛔ The act kind is a CLOSED member-selected discriminant. */
132	  if (typeof ao.act !== 'string' || !(MEMBER_ACT_KINDS as readonly string[]).includes(ao.act)) {
133	    return { ok: false, error: `act.act must be one of ${MEMBER_ACT_KINDS.join(', ')}` };
134	  }
