150	      return { ok: false, error: 'proposalPolicy must be allow or reply_only' };
151	    }
152	    proposalPolicy = b.proposalPolicy;
153	  }
154	  if (b.scope !== undefined) {
155	    if (typeof b.scope !== 'object' || b.scope === null || Array.isArray(b.scope)) {
156	      return { ok: false, error: 'scope must be an object' };
157	    }
158	    const so = b.scope as Record<string, unknown>;
159	    const strayScope = Object.keys(so).filter(
160	      (k) => !(SCOPE_KEYS as readonly string[]).includes(k));
161	    if (strayScope.length) {
162	      return { ok: false, error: `unknown scope field(s): ${strayScope.join(', ')}` };
163	    }
164	    if (so.latitude !== undefined && !isEditorialLatitude(so.latitude)) {
165	      return { ok: false, error: 'scope.latitude must be an integer 1 through 5' };
166	    }
167	    if (!(so.mayRemoveParagraphs === undefined || typeof so.mayRemoveParagraphs === 'boolean')) {
168	      return { ok: false, error: 'scope.mayRemoveParagraphs must be a boolean' };
169	    }
170	    if (!(so.mayProposeImmediately === undefined || typeof so.mayProposeImmediately === 'boolean')) {
171	      return { ok: false, error: 'scope.mayProposeImmediately must be a boolean' };
172	    }
173	    mayProposeImmediately = so.mayProposeImmediately === true;
174	    scope = {
175	      latitude: so.latitude === undefined
176	        ? DEFAULT_SCOPE_DECLARATION.latitude : so.latitude,
177	      /* ⛔ `=== true`, so any other value is refused permission rather than
178	         truthy-coerced into it. */
179	      mayRemoveParagraphs: so.mayRemoveParagraphs === true,
180	    };
181	  }
