183	  return {
184	    ok: true,
185	    threadId: b.threadId,
186	    /* ⛔ The member's text is carried EXACTLY. No trim, no normalisation. */
187	    act: { act: ao.act as MemberActKind, text: ao.text, refersTo: ao.refersTo ?? null },
188	    /* ⭐ Validated as a boolean above; minted from the WHOLE body so a
189	       contradictory nested affirmative still fails closed to Sanctuary. */
190	    sanctuary: TurnPosture.resolve(b).sanctuary,
191	    scope,
192	    relationshipId: typeof b.relationshipId === 'string' ? b.relationshipId : null,
193	    carry,
194	    mayProposeImmediately,
195	    proposalPolicy,
196	  };
197	}
