355	    version: turn.persisted.version ? { id: turn.persisted.version.id } : null,
356	    /* ⭐⭐ WHAT THE SUGGESTION BROUGHT IN THAT IS NOT THE WRITER'S.
357	     *
358	     * ⛔ Carried on SUCCESS, deliberately. It is a thing to notice, not a thing
359	     * to fail — and for a writer still finding their voice, noticing in time is
360	     * the whole of the protection. */
361	    voice: turn.voice,
362	  });
