296	    answeredAt: outcome.provenance.answeredAt,
297	    readerVersion: outcome.provenance.readerVersion,
298	    cognitionInputFingerprint,
299	    durableEffect: 'NONE',
300	  } as const;
301	
302	  let turnIndex: number;
303	  try {
304	    turnIndex = await transaction(async (client) => {
305	      const preparedRelationship = relationshipId !== null
306	        ? await prepareRelationshipForAppendWithClient(client, { memberId, relationshipId })
307	        : null;
308	
309	      const index = await appendTurnWithClient(client, {
310	        threadId,
311	        memberId,
312	        speaker: 'maia',
313	        body: outcome.answer,
314	        staleness,
315	        answerProvenance,
316	      });
317	      for (const crossing of crossings) {
318	        await confirmDisclosureCrossedWithClient(client, crossing.disclosureId);
319	      }
320	      await recordCompletionWithClient(client, authorizationRef, `${threadId}:${index}`);
321	      if (preparedRelationship && relationshipId !== null) {
322	        await appendReviewDiscussEpisodeWithClient(client, preparedRelationship, {
323	          threadId,
324	          maiaTurnIndex: index,
325	          authorizationId: authorizationRef,
326	          readingId,
327	          observationKey,
328	        });
329	      }
330	      return index;
331	    });
332	  } catch (error) {
333	    if (error instanceof RelationshipCustodyRefused) {
334	      return NextResponse.json(
335	        { refusal: 'relationship_unavailable', detail: error.reason, threadId },
336	        { status: 409 },
337	      );
338	    }
339	    console.error('[R2-2] Review Discuss post-cognition tail rolled back');
340	    return NextResponse.json(
341	      { refusal: 'answer_not_recorded', threadId },
342	      { status: 500 },
343	    );
344	  }
345	
346	  return NextResponse.json({
347	    threadId,
348	    turnIndex,
349	    posture: 'AS_READ',
350	    location: ctx.location,
351	    answer: outcome.answer,
352	    provenance: answerProvenance,
353	  });
354	}
